:root[lwt-tree-brighttext] #unifinder-searchBox {
  --toolbarbutton-background-color-hover: var(
    --lwt-toolbarbutton-hover-background,
    rgba(255, 255, 255, 0.25)
  );
  --toolbarbutton-hover-bordercolor: var(
    --lwt-toolbarbutton-hover-background,
    rgba(255, 255, 255, 0.5)
  );
  --toolbarbutton-header-bordercolor: var(
    --lwt-toolbarbutton-hover-background,
    rgba(255, 255, 255, 0.25)
  );
  --toolbarbutton-background-color-active: var(
    --lwt-toolbarbutton-active-background,
    rgba(255, 255, 255, 0.4)
  );
  --toolbarbutton-active-bordercolor: var(
    --lwt-toolbarbutton-active-background,
    rgba(255, 255, 255, 0.7)
  );
  --toolbarbutton-active-boxshadow: 0 0 0 1px
    var(--lwt-toolbarbutton-active-background, rgba(255, 255, 255, 0.4)) inset;
  --toolbarbutton-checked-background: var(
    --lwt-toolbarbutton-hover-background,
    rgba(255, 255, 255, 0.3)
  );
}

#unifinder-search-field {
  flex: 1;
  --input-text-max-width: none;
}

/* only format Unifinder lists */
#unifinder-search-results-tree > treechildren::-moz-tree-cell-text(highpriority) {
  font-weight: bold;
}

#unifinder-search-results-tree > treechildren::-moz-tree-cell-text(lowpriority) {
  font-style: italic;
  opacity: 0.6;
}

#unifinder-search-results-tree {
  appearance: none;
  margin: 0;
  border: none;
}

:root[lwt-tree] #unifinder-searchBox {
  background-color: var(--toolbar-background-color);
  background-image: none;
  color: var(--toolbar-text-color);
}
